export type TranslationCatalog = MessageShape;
export type TranslationKey = keyof TranslationCatalog;
export type TranslationValue<K extends TranslationKey> = TranslationCatalog[K];
export type TranslationParams<K extends TranslationKey> =
  TranslationValue<K> extends (params: infer T) => string ? T : never;

export const I18N_MESSAGES: Readonly<Record<SupportedLanguage, TranslationCatalog>> = {
  ru: ruMessages,
  en: enMessages,
  fr: frMessages,
  de: deMessages,
  bg: bgMessages,
};
